#include <stdio.h>

long long max(long long a, long long b) {
    return a > b ? a : b;
}

int main() {
    int N, W;
    scanf("%d %d", &N, &W);

    int w[101];
    int v[101];
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &w[i], &v[i]);
    }

    long long dp[100001] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = W; j >= w[i]; j--) {
            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
        }
    }

    long long answer = 0;
    for (int j = 0; j <= W; j++) {
        answer = max(answer, dp[j]);
    }

    printf("%lld\n", answer);

    return 0;
}

