#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, W;
    if (scanf("%d %d", &N, &W) != 2) return 0;

    long long *dp = (long long *)calloc(W + 1, sizeof(long long));
    if (!dp) return 0;

    for (int i = 0; i < N; i++) {
        int w, v;
        scanf("%d %d", &w, &v);

        for (int weight = W; weight >= w; weight--) {
            long long candidate = dp[weight - w] + v;
            if (candidate > dp[weight]) dp[weight] = candidate;
        }
    }

    long long ans = 0;
    for (int weight = 0; weight <= W; weight++) {
        if (dp[weight] > ans) ans = dp[weight];
    }

    printf("%lld\n", ans);
    free(dp);
    return 0;
}

