    }

    // dp[j] = maximum value achievable with weight exactly j
    // Initialize with -1 (unreachable) except dp[0] = 0
    vector<long long> dp(W + 1, -1);
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        // Process in reverse to avoid using the same item multiple times
        for (int j = W; j >= w[i]; j--) {
            if (dp[j - w[i]] != -1) {
                dp[j] = max(dp[j], dp[j - w[i]] + v[i]);
            }
        }
    }

    long long ans = 0;
    for (int j = 0; j <= W; j++) {
        ans = max(ans, dp[j]);
    }

    cout << ans << "\n";

    return 0;
}

