import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int W = sc.nextInt();

        int[] weight = new int[N];
        int[] value = new int[N];

        for (int i = 0; i < N; i++) {
            weight[i] = sc.nextInt();
            value[i] = sc.nextInt();
        }

        // dp[w] = maximum value achievable with exactly weight w
        long[] dp = new long[W + 1];
        Arrays.fill(dp, Long.MIN_VALUE);
        dp[0] = 0;

        for (int i = 0; i < N; i++) {
            int w = weight[i];
            int v = value[i];
            // iterate backwards to avoid using the same item multiple times
            for (int j = W; j >= w; j--) {
                if (dp[j - w] != Long.MIN_VALUE) {
                    dp[j] = Math.max(dp[j], dp[j - w] + v);
                }
            }
        }

        long maxVal = 0;
        for (int j = 0; j <= W; j++) {
            maxVal = Math.max(maxVal, dp[j]);
        }

        System.out.println(maxVal);
        sc.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long W = fs.nextLong();

        long[] dp = new long[(int) W + 1];

        for (int i = 0; i < N; i++) {
            int weight = fs.nextInt();
            long value = fs.nextLong();

            for (int w = (int) W; w >= weight; w--) {
                dp[w] = Math.max(dp[w], dp[w - weight] + value);
            }
        }

        long ans = 0;
        for (int w = 0; w <= W; w++) ans = Math.max(ans, dp[w]);

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

